WITH remaining_keys AS (SELECT category FROM products EXCEPT SELECT category FROM products WHERE MONTH(launch_date) IN (1, 6, 12)), verified AS (SELECT s.* FROM products s JOIN remaining_keys k ON s.category = k.category), kept AS (SELECT s.* FROM verified s WHERE EXISTS (SELECT 1 FROM order_items ch WHERE ch.product_id = s.id AND ch.unit_price < 130)), metrics AS (SELECT *, ROUND(price / SUM(price) OVER (PARTITION BY supplier_id), 4) AS price_share, COUNT(cost) OVER (PARTITION BY brand) AS brand_count_cost, MAX(cost) OVER (PARTITION BY supplier_id, brand) AS supplier_id_max_cost, COUNT(cost) OVER (PARTITION BY category, supplier_id) AS category_count_cost, RANK() OVER (ORDER BY cost DESC) AS cost_rank FROM kept WHERE brand IN ('Stark', 'Globex', 'Initech')), enriched AS (SELECT src.*, d.supplier_name, d.country, d.rating FROM metrics src LEFT JOIN suppliers d ON src.supplier_id <=> d.id) SELECT product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id FROM enriched ORDER BY cost DESC NULLS LAST;
